(function(root){'use strict';const C=typeof module!=='undefined'?require('./core.js'):root.ArcadeCore;
const maps=[['AAAA','BCCD','BCCD','BBDD'],['AAABB','ACBBB','ACDDD','CCDDD'],['AABBB','AACBD','EECDD','EECDD'],['AAA##','ABBCD','EBBCD','EFFCD','EFFGG']];
const levels=maps.map((map,i)=>{const labels=[...new Set(map.join('').replaceAll('#',''))];return{id:'patch-'+(i+1),name:['First stitches','Long way round','The golden seal','Secret garden'][i],subtitle:['Fit every patch. Turn pieces to find their place.','New silhouettes: a long hook and a broad patch.','The golden patch must cover the marked flower.','A stone corner and a mirrored patch change the plan.'][i],w:map[0].length,h:map.length,blocked:map.flatMap((row,y)=>[...row].flatMap((v,x)=>v==='#'?[[x,y]]:[])),pieces:labels.map((label,n)=>{const cells=map.flatMap((row,y)=>[...row].flatMap((v,x)=>v===label?[[x,y]]:[]));const normalized=C.rotate(cells);return{id:label,cells:i===3&&n===0?C.rotate(normalized,0,true):normalized,color:n};}),mark:i>=2?{x:2,y:1,piece:i===2?'C':'B'}:null,mirror:i===3,par:labels.length+2,solution:map};});
function create(level){return{level,placements:{},selected:level.pieces[0].id,turn:0,mirror:false,moves:0,history:[]};}
function cells(model,id=model.selected,x=0,y=0){const p=model.level.pieces.find(p=>p.id===id);return C.rotate(p.cells,model.turn,model.mirror).map(([a,b])=>[a+x,b+y]);}
function occupied(m){const out={};for(const [id,p]of Object.entries(m.placements))for(const [x,y]of C.rotate(m.level.pieces.find(v=>v.id===id).cells,p.turn,p.mirror))out[(x+p.x)+','+(y+p.y)]=id;return out;}
function valid(m,x,y){if(m.placements[m.selected])return false;const taken=occupied(m),l=m.level;return cells(m,m.selected,x,y).every(([a,b])=>a>=0&&a<l.w&&b>=0&&b<l.h&&!l.blocked.some(([xx,yy])=>a===xx&&b===yy)&&!taken[a+','+b]&&(!l.mark||a!==l.mark.x||b!==l.mark.y||m.selected===l.mark.piece));}
function place(m,x,y){if(!valid(m,x,y))return false;m.history.push(C.copy(m.placements));m.placements[m.selected]={x,y,turn:m.turn,mirror:m.mirror};m.moves++;const next=m.level.pieces.find(p=>!m.placements[p.id]);if(next)m.selected=next.id;m.turn=0;m.mirror=false;return true;}
function remove(m,id){if(!m.placements[id])return false;m.history.push(C.copy(m.placements));delete m.placements[id];m.selected=id;m.turn=0;m.mirror=false;m.moves++;return true;}
function undo(m){if(!m.history.length)return false;m.placements=m.history.pop();m.moves++;return true;}
function solved(m){return Object.keys(occupied(m)).length===m.level.w*m.level.h-m.level.blocked.length&&(!m.level.mark||occupied(m)[m.level.mark.x+','+m.level.mark.y]===m.level.mark.piece);}
function score(m){return Math.max(100,1200-Math.max(0,m.moves-m.level.pieces.length)*45);}
const api={id:'block',title:'Block Puzzle',tag:'THE PATCHWORK CONSERVATORY',instructions:'Fill the frame with every embroidered patch. Select a piece, rotate it, then tap its top-left board cell. Tap a placed patch to lift it. Later levels add a flower seal, a stone corner, and mirroring. Undo is always available.',levels,create,cells,occupied,valid,place,remove,undo,solved,score};if(typeof module!=='undefined')module.exports=api;root.ArcadeGames=root.ArcadeGames||{};root.ArcadeGames.block=api;
})(typeof window!=='undefined'?window:globalThis);
